<p>개별 종목 선택이 어렵다면 고배당 ETF를 활용하는 것이 방법입니다. 여러 고배당 종목에 분산투자되어 있으므로 리스크가 낮고, 정기적으로 배당금을 받을 수 있습니다.</p>

