<p>관련 글: <a href="/blog/코스피-6000-시대-지금-들어가도-늦지-않았나요" style="color: var(--color-brand);">코스피 6000 시대 투자 가이드</a> | <a href="/blog/반도체-AI-투자-전략-HBM4-시대의-기회와-리스크" style="color: var(--color-brand);">반도체·AI 투자 전략</a> | <a href="/blog/배당주-투자-가이드" style="color: var(--color-brand);">배당주 투자 가이드</a></p>
