<p>상반기 코스피는 반도체·AI 슈퍼사이클, 외국인 자금 유입, 금리 인하 기대감 등의 요인에 힘입어 50% 이상 상승했습니다. 하반기에도 이러한 상승 모멘텀이 지속될지, 아니면 조정이 올지가 핵심 관심사입니다.</p>

