<p>자사주 소각이 주주 가치 제고로 연결되는 원리는 생각보다 단순합니다. 피자를 예로 들어보겠습니다. 같은 크기의 피자를 여러 조각으로 나누어 가진다고 할 때, 조각 수가 줄어들면 남은 한 조각의 비중은 커집니다. 기업도 비슷합니다. 회사의 전체 가치가 그대로라고 가정할 때, 발행주식 수가 줄어들면 한 주가 대표하는 회사 지분 비율은 높아집니다. 이때 주당순이익, 주당순자산, 주당배당 여력 같은 지표가 개선되어 보일 수 있습니다. 특히 이익이 꾸준한 기업이 잉여현금으로 자사주를 매입하고 소각한다면, 기존 주주 입장에서는 회사의 이익을 나눌 주식 수가 줄어드는 효과를 기대할 수 있습니다. 그래서 시장은 단순한 이벤트보다 <b>실제 주당 가치가 개선되는 구조</b>에 더 긍정적으로 반응하는 경우가 많습니다.</p>
