<thead>
<tr>
<th>구분</th>
<th>특징</th>
<th>추천 대상</th>
</tr>
</thead>
<tbody>
<tr>
<td><b>주식 중심</b></td>
<td>장기 성장성이 높지만 변동성도 큽니다.</td>
<td>장기 투자자</td>
</tr>
