<p><span>하단 밴드 이탈 반전 매매 전략</span></p>
<div>
<p>하단 밴드 이탈은 많은 투자자가 저가 매수 기회로 보는 구간입니다. 하지만 실전에서는 하단 밴드 이탈 직후 무작정 매수하면 손실이 커질 수 있습니다. 강한 하락 추세에서는 주가가 하단 밴드 아래로 계속 밀리며 중심선과의 거리가 더 벌어지기도 합니다. 그래서 반전 매매를 할 때는 하단 밴드에 닿았다는 사실보다 <b>매도 압력이 약해지는 흔적</b>을 확인해야 합니다. 예를 들어 긴 아랫꼬리가 나오거나, 밴드 밖에서 마감하지 못하고 밴드 안으로 다시 들어오거나, 다음 캔들이 전일 고가를 회복하는 모습은 반전 가능성을 높여줍니다. 반전 매매에서 가장 조심할 구간은 하락 추세가 뚜렷한데 거래량까지 터지며 하단 밴드를 이탈하는 경우입니다. 이때는 공포가 커져 단기 반등이 나올 수 있지만, 반등이 약하면 다시 하락이 이어질 수 있습니다.</p>
