<p><span>매집 신호와 물량 털기를 구분하는 기준</span></p>
<div>
<p>바닥권 대량 거래량을 볼 때 가장 어려운 부분은 매집인지 물량 털기인지 구분하는 것입니다. 겉으로 보면 둘 다 거래량이 많고 주가가 흔들립니다. 하지만 자세히 보면 차이가 있습니다. 매집 가능성이 있는 구간에서는 대량 거래 이후 주가가 이전 저점을 쉽게 깨지 않고, 조정이 나와도 거래량이 줄어드는 경우가 많습니다. 이는 강한 매도 압력이 반복적으로 나오지 않는다는 뜻으로 해석할 수 있습니다. 반대로 물량 털기 구간에서는 거래량이 터진 뒤 주가가 빠르게 무너지고, 반등이 나와도 매물에 막히는 경우가 많습니다. 특히 바닥처럼 보였던 자리가 깨지면서 거래량이 다시 증가하면 손절 물량과 실망 매물이 동시에 쏟아질 수 있습니다. 차트를 볼 때 가장 경계하는 패턴은 대량 거래량 장대양봉 이후 바로 다음 며칠 동안 종가가 양봉의 중심 아래로 밀리는 흐름입니다. 이런 경우 첫날의 강한 매수세가 유지되지 못했다는 의미일 수 있습니다. 반대로 대량 거래 이후 주가가 조금 밀리더라도 종가 기준으로 주요 지지선을 지키고, 거래량이 줄며 조용히 버티면 매물 소화 가능성을 봅니다. 결국 핵심은 거래량이 터진 날이 아니라 그 이후의 반응입니다. 세력 매집은 조용히 시간을 끌며 물량을 모으는 과정일 수 있고, 물량 털기는 사람들의 기대가 몰린 순간 빠르게 매물을 넘기는 과정일 수 있습니다.</p>
