<div>
<div><span>🧮</span> <span><b>기본 계산:</b> 연간 1주당 배당금을 현재 주가 또는 내 매수가로 나누어 계산합니다.</span></div>
<div><span>📌</span> <span><b>내 기준 수익률:</b> 화면상 수익률보다 내 실제 매수가 기준 배당수익률이 더 중요합니다.</span></div>
<div><span>⚠️</span> <span><b>착시 주의:</b> 주가 급락으로 배당수익률이 높아진 종목은 배당 삭감 가능성도 함께 봐야 합니다.</span></div>
<div><span>📈</span> <span><b>실전 판단:</b> 배당수익률, 배당성향, 이익 흐름, 현금흐름을 함께 확인해야 합니다.</span></div>
<p>배당수익률은 높을수록 좋은 숫자가 아니라 유지될 수 있을 때 의미 있는 숫자입니다.</p>
</div>
