<p>60일선은 약 3개월 정도의 평균 가격을 보여주는 중기 이동평균선입니다. 5일선과 20일선보다 느리게 움직이기 때문에 단기 변동에는 둔감하지만, 큰 흐름을 판단할 때는 매우 유용합니다. 특히 주가가 60일선 위에 있는지 아래에 있는지는 종목의 중기 체력을 확인하는 데 도움이 됩니다. 60일선이 중요한 이유는 단기 반등이 진짜 추세 전환인지, 아니면 하락 중 잠깐의 반등인지 구분하는 데 도움을 주기 때문입니다. 주가가 60일선 아래에서 계속 움직이면 위로 올라갈 때마다 매물 부담이 생길 수 있고, 60일선을 강하게 돌파한 뒤 지지까지 확인하면 중기 흐름이 바뀌는 신호로 볼 수 있습니다. 다만 60일선은 느린 선이기 때문에 단기 매수 타이밍을 아주 정확하게 잡기보다는 <b>큰 방향과 리스크 위치</b>를 판단하는 기준으로 활용하는 것이 좋습니다.</p>
